        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ILoadoutGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            foreach (var item in obj.ActorEffects)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.PerkCard, out var PerkCardInfo))
            {
                yield return PerkCardInfo;
            }
            if (FormLinkInformation.TryFactory(obj.EquippedPerk, out var EquippedPerkInfo))
            {
                yield return EquippedPerkInfo;
            }
            if (FormLinkInformation.TryFactory(obj.InventoryItem, out var InventoryItemInfo))
            {
                yield return InventoryItemInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MaxLevel, out var MaxLevelInfo))
            {
                yield return MaxLevelInfo;
            }
            yield break;
        }
        
