        }
        
        public void DeepCopyIn(
            ILoadout item,
            ILoadoutGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout76MajorRecord)item,
                (IFallout76MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.EDID) ?? true))
            {
                item.EDID = rhs.EDID;
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.FULL) ?? true))
            {
                item.FULL = rhs.FULL?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.DESC) ?? true))
            {
                item.DESC = rhs.DESC?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.SPCT) ?? true))
            {
                item.SPCT = rhs.SPCT;
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.ActorEffects) ?? true))
            {
                errorMask?.PushIndex((int)Loadout_FieldIndex.ActorEffects);
                try
                {
                    item.ActorEffects.SetTo(
                        rhs.ActorEffects
                            .Select(b => (IFormLinkGetter<ISpellGetter>)new FormLink<ISpellGetter>(b.FormKey)));
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.SPLO2) ?? true))
            {
                if(rhs.SPLO2 is {} SPLO2rhs)
                {
                    item.SPLO2 = SPLO2rhs.ToArray();
                }
                else
                {
                    item.SPLO2 = default;
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.PerkCard) ?? true))
            {
                item.PerkCard.SetTo(rhs.PerkCard.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.EquippedPerk) ?? true))
            {
                item.EquippedPerk.SetTo(rhs.EquippedPerk.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.InventoryItem) ?? true))
            {
                item.InventoryItem.SetTo(rhs.InventoryItem.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.MaxLevel) ?? true))
            {
                item.MaxLevel.SetTo(rhs.MaxLevel.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.LLVL) ?? true))
            {
                item.LLVL = rhs.LLVL;
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.NAM0) ?? true))
            {
                item.NAM0 = rhs.NAM0;
            }
            if ((copyMask?.GetShouldTranslate((int)Loadout_FieldIndex.LSPC) ?? true))
            {
                if(rhs.LSPC is {} LSPCrhs)
                {
                    item.LSPC = LSPCrhs.ToArray();
                }
                else
                {
                    item.LSPC = default;
                }
            }
            DeepCopyInCustom(
                item: item,
                rhs: rhs,
                errorMask: errorMask,
                copyMask: copyMask,
                deepCopy: deepCopy);
        }
        
