    internal partial class LoadoutBinaryCreateTranslation : Fallout76MajorRecordBinaryCreateTranslation
    {
        public new static readonly LoadoutBinaryCreateTranslation Instance = new LoadoutBinaryCreateTranslation();

        public override RecordType RecordType => RecordTypes.LOUT;
        public static ParseResult FillBinaryRecordTypes(
            ILoadoutInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                            item: item,
                            frame: frame,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            nextRecordType: nextRecordType,
                            contentLength: contentLength,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                        item.EDID = StringBinaryTranslation.Instance.Parse(
                            reader: frame.SpawnWithLength(contentLength),
                            stringBinaryType: StringBinaryType.NullTerminate,
                            parseWhole: true);
                        return new ParseResult((int)Loadout_FieldIndex.EDID, nextRecordType);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(nextRecordType) ?? 0)
                        {
                            case 0:
                                return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                                    item: item,
                                    frame: frame,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    nextRecordType: nextRecordType,
                                    contentLength: contentLength,
                                    translationParams: translationParams.WithNoConverter());
                            case 1:
                                frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                                item.EDID = StringBinaryTranslation.Instance.Parse(
                                    reader: frame.SpawnWithLength(contentLength),
                                    stringBinaryType: StringBinaryType.NullTerminate,
                                    parseWhole: true);
                                return new ParseResult((int)Loadout_FieldIndex.EDID, nextRecordType);
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.FULL:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FULL = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)Loadout_FieldIndex.FULL;
                }
                case RecordTypeInts.DESC:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.DESC = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        eager: true,
                        source: StringsSource.Normal,
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)Loadout_FieldIndex.DESC;
                }
                case RecordTypeInts.SPCT:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.SPCT = frame.ReadUInt32();
                    return (int)Loadout_FieldIndex.SPCT;
                }
                case RecordTypeInts.SPLO:
                {
                    if (!lastParsed.ParsedIndex.HasValue
                        || lastParsed.ParsedIndex.Value <= (int)Loadout_FieldIndex.SPCT)
                    {
                        item.ActorEffects.SetTo(
                            Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<IFormLinkGetter<ISpellGetter>>.Instance.Parse(
                                reader: frame,
                                triggeringRecord: translationParams.ConvertToCustom(RecordTypes.SPLO),
                                transl: FormLinkBinaryTranslation.Instance.Parse));
                        return new ParseResult((int)Loadout_FieldIndex.ActorEffects, nextRecordType);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Loadout_FieldIndex.ActorEffects)
                    {
                        frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                        item.SPLO2 = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                        return new ParseResult((int)Loadout_FieldIndex.SPLO2, nextRecordType);
                    }
                    else
                    {
